import{_ as e,c as s,o as t,a}from"./app.c36a9cce.js";const m=JSON.parse(`{"title":"Strict Mode","description":"","frontmatter":{},"headers":[{"level":2,"title":"What is StrictMode","slug":"what-is-strictmode","link":"#what-is-strictmode","children":[]},{"level":2,"title":"Saint-Bernard and StrictMode","slug":"saint-bernard-and-strictmode","link":"#saint-bernard-and-strictmode","children":[]},{"level":2,"title":"Don't use StrictMode","slug":"don-t-use-strictmode","link":"#don-t-use-strictmode","children":[]},{"level":2,"title":"Summary","slug":"summary","link":"#summary","children":[]}],"relativePath":"introduction/strict-mode.md"}`),o={name:"introduction/strict-mode.md"},n=a(`<h1 id="strict-mode" tabindex="-1">Strict Mode <a class="header-anchor" href="#strict-mode" aria-hidden="true">#</a></h1><p>A quick note on using the <code>StrictMode</code> component from the <code>react</code> library.</p><h2 id="what-is-strictmode" tabindex="-1">What is StrictMode <a class="header-anchor" href="#what-is-strictmode" aria-hidden="true">#</a></h2><p>The <code>StrictMode</code> component is a component that helps developers not forget to clean up any listeners, requests, WebSocket connections and so on.</p><p>Each time you use the <code>useEffect</code> in order to trigger a side-effect, you can also return a callback function that gets called whenever then component gets destroyed.</p><p>This is particularily useful if you have some components that gets destroyed and created often (like a page for instance), this helps reduce the numbers of listeners active for one component, as the previous listeners that were activated from previous renders might take up memory for nothing.</p><h2 id="saint-bernard-and-strictmode" tabindex="-1">Saint-Bernard and StrictMode <a class="header-anchor" href="#saint-bernard-and-strictmode" aria-hidden="true">#</a></h2><p>The <code>saint-bernard</code> library has already handled this for you, and whenever you use the <code>useStatefulRequest</code> or <code>useStatelessRequest</code> hooks, it automatically cleanup any ongoing request if the component that called these hooks gets destroyed.</p><p>This is essentially what is going on behind the scene of this library.</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki"><code><span class="line"><span style="color:#C792EA;">const</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span><span style="color:#A6ACCD;"> cancel </span><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">useStatefulRequest</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">intitialState</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> []</span></span>
<span class="line"><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#82AAFF;">useEffect</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">()</span><span style="color:#A6ACCD;"> </span><span style="color:#C792EA;">=&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#89DDFF;">return</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">()</span><span style="color:#F07178;"> </span><span style="color:#C792EA;">=&gt;</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">    </span><span style="color:#82AAFF;">cancel</span><span style="color:#F07178;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#89DDFF;">};</span></span>
<span class="line"><span style="color:#89DDFF;">},</span><span style="color:#A6ACCD;"> [])</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>Of course, you could do that, but that would be cumbersome, and you don&#39;t need to, this has already been done for you!</p><p>However, since this library has a strong emphasis on error handling, whenever a request has been canceled, it forces you to handle that case.</p><h2 id="don-t-use-strictmode" tabindex="-1">Don&#39;t use StrictMode <a class="header-anchor" href="#don-t-use-strictmode" aria-hidden="true">#</a></h2><p>We recommend you don&#39;t use StrictMode as <code>react</code> will in fact play you HTTP requests twice in order to show you that you forgot to cleanup any ongoing request on component destroy, however by doing so, you will always have the <code>CancelError</code> error being triggered, and you will be blocked since this error can&#39;t be ignored when using this library, you&#39;ll have to handle it by displaying a message in the screen of your user.</p><p>However, in development, this can be tedious to test with the <code>StrictMode</code> enabled.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-hidden="true">#</a></h2><p><code>StrictMode</code> is useful if you are creating your HTTP requests by hand since you could forgot to cleanup your HTTP requests, however this library has already done the work for you, so this component is not necessary, and can lead to a worse developer experience.</p>`,17),r=[n];function l(c,i,p,d,h,u){return t(),s("div",null,r)}const D=e(o,[["render",l]]);export{m as __pageData,D as default};
